INSERT INTO landing_pages (slug, label, is_published, cta_region_slug, image_url, og_image_url, image_alt, sort_order, focus_keyword_en, keywords_en, h1_en, intro_en, content_en, meta_title_en, meta_description_en, h1_tr, intro_tr, content_tr, meta_title_tr, meta_description_tr, h1_de, intro_de, content_de, meta_title_de, meta_description_de, h1_pl, intro_pl, content_pl, meta_title_pl, meta_description_pl, h1_ru, intro_ru, content_ru, meta_title_ru, meta_description_ru, h1_nl, intro_nl, content_nl, meta_title_nl, meta_description_nl, h1_ro, intro_ro, content_ro, meta_title_ro, meta_description_ro)
SELECT 'antalya-airport-transfer', 'Antalya Airport Transfer', true, NULL, 'https://ximlobdcblinqtlizwrz.supabase.co/storage/v1/object/public/blog-images/pages/1788358326157-62db47.png', 'https://ximlobdcblinqtlizwrz.supabase.co/storage/v1/object/public/blog-images/pages/1788358328246-l8roy0.png', 'Antalya Airport Transfer', 104, 'antalya airport transfer', 'transfer from antalya airport, private transfer antalya airport, airport transfer antalya, antalya private transfer', 'Antalya Airport Transfer', 'Private transfer from Antalya Airport (AYT) straight to your hotel — one fixed price per vehicle, with your driver waiting for you in the arrivals hall.', '<p>You book before you fly, we track your flight, and a Mercedes Vito takes you door to door. No queue at the taxi rank, no meter running, no surprise at the end of the ride.</p><h2>What happens when you land at Antalya Airport</h2><ol><li><strong>Book before you fly</strong> — Choose your destination, date and time. You get instant confirmation by email with your driver''s details and a QR code.</li><li><strong>We track your flight</strong> — Add your flight number when booking. We monitor all flights in real time — if yours is delayed, your driver waits for free.</li><li><strong>Meet &amp; greet in arrivals</strong> — Your driver is at the designated meeting point in the arrivals hall with a sign bearing your name, and helps you with your luggage to the vehicle.</li><li><strong>Door to door</strong> — Straight from the airport to your hotel, villa or any address on the Turkish Riviera — no other pickups, no detours.</li></ol><h2>Why book your Antalya Airport transfer with TORVIAN</h2><ul><li>Prices are per vehicle, not per person — up to 5 passengers travel in one Mercedes Vito for the same price.</li><li>The price you see at booking is the price you pay. No hidden fees, no surge pricing.</li><li>Every arrival at Antalya Airport is flight-tracked, so your driver is timed to your actual landing.</li><li>Free cancellation up to 24 hours before your scheduled departure time.</li><li>Child seats available for $10 per booking — just request one while booking.</li><li>We run transfers 24/7, so a late-night arrival is booked exactly like any other.</li><li>Mercedes Vito VIP vehicles with leather seats, Wi-Fi and climate control.</li><li>Card payments handled by Stripe on PCI DSS compliant infrastructure.</li></ul><h2>Frequently Asked Questions</h2><h3>How much does an Antalya Airport transfer cost?</h3><p>The price depends only on your destination and is fixed per vehicle, not per person — up to 5 passengers pay the same. Open the page for your destination to see its exact fixed price before you book.</p><h3>How will my driver find me at Antalya Airport?</h3><p>Your driver will be waiting at the designated meeting point in the arrivals hall with a sign bearing your name. After booking you receive an email with the driver''s details and a QR code.</p><h3>What happens if my flight is delayed?</h3><p>We track all flights in real time. If your flight is delayed, your driver waits for free.</p><h3>Are prices per person or per vehicle?</h3><p>Per vehicle. Up to 5 passengers can travel in a single Mercedes Vito at the same price, so a family pays the same as a solo traveller.</p><h3>Can I cancel my airport transfer for free?</h3><p>Yes, free cancellation is available up to 24 hours before your scheduled departure time.</p><h3>Do you run transfers at night?</h3><p>Yes, we provide transfer service 24/7. Your driver will be ready and waiting for night flights as well.</p><h3>Can I book a transfer with a child seat?</h3><p>Yes. Child seats are available for $10 per booking — request one during booking and it is fitted before your driver leaves for the airport.</p>', 'Antalya Airport Transfer | Fixed Price, Meet & Greet, Book Online', 'Book a private Antalya Airport transfer to your hotel with fixed prices, flight tracking and 24/7 support. Direct, comfortable and reliable service.', 'Antalya Havalimanı Transfer', 'Antalya Havalimanı''ndan (AYT) doğrudan otelinize özel transfer — araç başına tek sabit fiyat, varış salonunda sizi bekleyen şoför.', '<p>Uçmadan önce rezervasyonunuzu yaparsınız, uçuşunuzu takip ederiz ve Mercedes Vito sizi kapıdan kapıya götürür. Taksi kuyruğu yok, çalışan taksimetre yok, yolculuk sonunda sürpriz yok.</p><h2>Antalya Havalimanı''na indiğinizde ne oluyor?</h2><ol><li><strong>Uçmadan önce rezervasyon</strong> — Bölgenizi, tarihinizi ve saatinizi seçin. Şoför bilgileri ve QR kod içeren onay e-postası anında gelir.</li><li><strong>Uçuşunuzu takip ediyoruz</strong> — Rezervasyon sırasında uçuş kodunuzu girin. Tüm uçuşları gerçek zamanlı izliyoruz — uçuşunuz gecikirse şoförünüz ücretsiz olarak bekler.</li><li><strong>Varış salonunda karşılama</strong> — Şoförünüz varış salonundaki belirlenen buluşma noktasında, adınızın yazılı olduğu tabelayla sizi karşılar ve bagajlarınızla araca kadar eşlik eder.</li><li><strong>Kapıdan kapıya</strong> — Havalimanından doğrudan otelinize, villanıza veya Türk Rivierası''ndaki herhangi bir adrese — başka yolcu almadan, sapmadan.</li></ol><h2>Antalya Havalimanı transferinizi neden TORVIAN ile ayırtmalısınız?</h2><ul><li>Fiyatlar kişi başı değil araç başınadır — tek bir Mercedes Vito''da 5 yolcuya kadar aynı fiyatla seyahat edebilirsiniz.</li><li>Rezervasyonda gördüğünüz fiyat ödediğiniz fiyattır. Gizli ücret yok, yoğunluk zammı yok.</li><li>Antalya Havalimanı''na gelen her uçuş takip edilir; şoförünüz gerçek iniş saatinize göre planlanır.</li><li>Planlanan kalkış saatinden 24 saat öncesine kadar ücretsiz iptal hakkınız vardır.</li><li>Çocuk koltuğu rezervasyon başına 10 dolar — rezervasyon sırasında talep etmeniz yeterli.</li><li>7/24 transfer hizmeti veriyoruz; gece geç saatteki bir varış da diğerleri gibi ayırtılır.</li><li>Deri koltuklu, Wi-Fi ve klima donanımlı Mercedes Vito VIP araçlar.</li><li>Kart ödemeleri PCI DSS uyumlu Stripe altyapısı üzerinden alınır.</li></ul><h2>Sık Sorulan Sorular</h2><h3>Antalya Havalimanı transferi ne kadar tutuyor?</h3><p>Fiyat yalnızca gideceğiniz bölgeye göre değişir ve kişi başı değil araç başına sabittir — 5 yolcuya kadar aynı ücreti ödersiniz. Rezervasyondan önce net fiyatı görmek için bölgenizin sayfasını açın.</p><h3>Havalimanında şoförüm beni nasıl bulacak?</h3><p>Şoförünüz varış salonundaki belirlenen buluşma noktasında, adınızın yazılı olduğu tabelayla bekliyor olacak. Rezervasyon sonrası şoför bilgileri ve QR kodu içeren bilgilendirme e-postası gönderilir.</p><h3>Uçuşum rötar yaparsa ne olur?</h3><p>Tüm uçuşları gerçek zamanlı takip ediyoruz. Uçuşunuz gecikirse şoförünüz ücretsiz olarak bekler.</p><h3>Fiyatlar kişi başı mı, araç başına mı?</h3><p>Araç başınadır. Tek bir Mercedes Vito''da 5 yolcuya kadar aynı fiyatla seyahat edebilirsiniz; yani bir aile tek kişiyle aynı ücreti öder.</p><h3>Havalimanı transferimi ücretsiz iptal edebilir miyim?</h3><p>Evet, planlanan kalkış saatinden 24 saat öncesine kadar ücretsiz iptal hakkınız bulunmaktadır.</p><h3>Gece transfer yapıyor musunuz?</h3><p>Evet, 7/24 transfer hizmeti sunuyoruz. Gece uçuşları için de şoförünüz hazır olacaktır.</p><h3>Çocuk koltuklu transfer ayırtabilir miyim?</h3><p>Evet. Çocuk koltuğu rezervasyon başına 10 dolardır — rezervasyon sırasında talep edin, şoförünüz havalimanına çıkmadan önce araca takılır.</p>', 'Antalya Havalimanı Transfer | Sabit Fiyat, Karşılama, Online Rezervasyon', 'Antalya Havalimanı özel transfer: araç başına sabit fiyat, gerçek zamanlı uçuş takibi ve varış salonunda sizi bekleyen şoför. 24 saat öncesine kadar ücretsiz iptal.', 'Flughafen Antalya Transfer', 'Privater Transfer vom Flughafen Antalya (AYT) direkt zu Ihrem Hotel — ein Festpreis pro Fahrzeug, Ihr Fahrer erwartet Sie in der Ankunftshalle.', '<p>Sie buchen vor dem Abflug, wir verfolgen Ihren Flug, und ein Mercedes Vito bringt Sie von Tür zu Tür. Keine Warteschlange am Taxistand, kein laufendes Taxameter, keine Überraschung am Ende der Fahrt.</p><h2>Was passiert, wenn Sie am Flughafen Antalya landen</h2><ol><li><strong>Vor dem Abflug buchen</strong> — Wählen Sie Zielort, Datum und Uhrzeit. Sie erhalten sofort eine Bestätigung per E-Mail mit den Fahrerdaten und einem QR-Code.</li><li><strong>Wir verfolgen Ihren Flug</strong> — Geben Sie bei der Buchung Ihre Flugnummer an. Wir verfolgen alle Flüge in Echtzeit — bei Verspätung wartet Ihr Fahrer kostenlos.</li><li><strong>Meet &amp; Greet in der Ankunftshalle</strong> — Ihr Fahrer erwartet Sie am designierten Treffpunkt in der Ankunftshalle mit einem Schild mit Ihrem Namen und begleitet Sie mit Ihrem Gepäck zum Fahrzeug.</li><li><strong>Von Tür zu Tür</strong> — Direkt vom Flughafen zu Ihrem Hotel, Ihrer Villa oder jeder Adresse an der Türkischen Riviera — ohne Zwischenstopps, ohne Umwege.</li></ol><h2>Warum Sie Ihren Flughafentransfer mit TORVIAN buchen</h2><ul><li>Die Preise gelten pro Fahrzeug, nicht pro Person — bis zu 5 Passagiere reisen im selben Mercedes Vito zum gleichen Preis.</li><li>Der Preis bei der Buchung ist der Preis, den Sie zahlen. Keine versteckten Gebühren, keine dynamischen Aufschläge.</li><li>Jede Ankunft am Flughafen Antalya wird per Flugverfolgung überwacht, Ihr Fahrer ist auf Ihre tatsächliche Landung getaktet.</li><li>Kostenlose Stornierung bis 24 Stunden vor der geplanten Abfahrt.</li><li>Kindersitze für 10 $ pro Buchung — geben Sie den Wunsch einfach bei der Buchung an.</li><li>Wir fahren rund um die Uhr, ein später Nachtflug wird genauso gebucht wie jeder andere Transfer.</li><li>Mercedes Vito VIP-Fahrzeuge mit Ledersitzen, WLAN und Klimaanlage.</li><li>Kartenzahlungen laufen über Stripe auf PCI-DSS-konformer Infrastruktur.</li></ul><h2>Häufig gestellte Fragen</h2><h3>Was kostet ein Transfer ab Flughafen Antalya?</h3><p>Der Preis hängt allein von Ihrem Zielort ab und gilt als Festpreis pro Fahrzeug, nicht pro Person — bis zu 5 Passagiere zahlen dasselbe. Öffnen Sie die Seite Ihres Zielorts, um den genauen Festpreis vor der Buchung zu sehen.</p><h3>Wie findet mich mein Fahrer am Flughafen?</h3><p>Ihr Fahrer erwartet Sie am designierten Treffpunkt in der Ankunftshalle mit einem Schild mit Ihrem Namen. Nach der Buchung erhalten Sie per E-Mail die Fahrerdaten und einen QR-Code.</p><h3>Was passiert, wenn mein Flug Verspätung hat?</h3><p>Wir verfolgen alle Flüge in Echtzeit. Bei Verspätung wartet Ihr Fahrer kostenlos.</p><h3>Gelten die Preise pro Person oder pro Fahrzeug?</h3><p>Pro Fahrzeug. Bis zu 5 Passagiere können in einem Mercedes Vito zum gleichen Preis reisen — eine Familie zahlt also so viel wie ein Alleinreisender.</p><h3>Kann ich meinen Flughafentransfer kostenlos stornieren?</h3><p>Ja, eine kostenlose Stornierung ist bis zu 24 Stunden vor der geplanten Abfahrt möglich.</p><h3>Fahren Sie auch nachts?</h3><p>Ja, wir bieten 24/7 Transferservice an. Ihr Fahrer ist auch bei Nachtflügen bereit und wartet.</p><h3>Kann ich einen Transfer mit Kindersitz buchen?</h3><p>Ja. Kindersitze sind für 10 $ pro Buchung verfügbar — geben Sie dies bei der Buchung an, dann ist der Sitz montiert, bevor Ihr Fahrer zum Flughafen aufbricht.</p>', 'Flughafen Antalya Transfer | Festpreis, Meet & Greet, Online buchen', 'Privater Transfer ab Flughafen Antalya: Festpreis pro Fahrzeug, Flugverfolgung in Echtzeit und Ihr Fahrer wartet in der Ankunftshalle. Kostenlose Stornierung bis 24 Std.', 'Transfer z Lotniska Antalya', 'Prywatny transfer z lotniska Antalya (AYT) prosto do Twojego hotelu — jedna stała cena za pojazd, kierowca czeka na Ciebie w hali przylotów.', '<p>Rezerwujesz przed wylotem, my śledzimy Twój lot, a Mercedes Vito zawozi Cię od drzwi do drzwi. Bez kolejki na postoju taksówek, bez taksometru, bez niespodzianek na końcu kursu.</p><h2>Co się dzieje, gdy lądujesz na lotnisku Antalya</h2><ol><li><strong>Rezerwacja przed wylotem</strong> — Wybierz destynację, datę i godzinę. Natychmiast otrzymasz e-mail z potwierdzeniem, danymi kierowcy i kodem QR.</li><li><strong>Śledzimy Twój lot</strong> — Podaj numer lotu przy rezerwacji. Śledzimy wszystkie loty w czasie rzeczywistym — jeśli Twój lot jest opóźniony, kierowca czeka bezpłatnie.</li><li><strong>Powitanie w hali przylotów</strong> — Kierowca czeka w wyznaczonym punkcie spotkania w hali przylotów z tabliczką z Twoim nazwiskiem i pomaga z bagażem do pojazdu.</li><li><strong>Od drzwi do drzwi</strong> — Prosto z lotniska do Twojego hotelu, willi lub dowolnego adresu na Riwierze Tureckiej — bez dodatkowych postojów i objazdów.</li></ol><h2>Dlaczego warto zarezerwować transfer z lotniska Antalya w TORVIAN</h2><ul><li>Ceny są za pojazd, nie od osoby — do 5 pasażerów podróżuje jednym Mercedesem Vito w tej samej cenie.</li><li>Cena widoczna przy rezerwacji to cena, którą płacisz. Bez ukrytych opłat i dopłat za szczyt.</li><li>Każdy przylot na lotnisko Antalya jest monitorowany, więc kierowca jest dopasowany do faktycznej godziny lądowania.</li><li>Darmowa anulacja do 24 godzin przed planowanym odjazdem.</li><li>Foteliki dziecięce za $10 za rezerwację — wystarczy zaznaczyć przy rezerwacji.</li><li>Jeździmy 24/7, więc nocny przylot rezerwuje się dokładnie tak samo jak każdy inny.</li><li>Pojazdy Mercedes Vito VIP ze skórzanymi fotelami, Wi-Fi i klimatyzacją.</li><li>Płatności kartą obsługuje Stripe na infrastrukturze zgodnej z PCI DSS.</li></ul><h2>Najczęściej zadawane pytania</h2><h3>Ile kosztuje transfer z lotniska Antalya?</h3><p>Cena zależy wyłącznie od destynacji i jest stała za pojazd, nie od osoby — do 5 pasażerów płaci tyle samo. Otwórz stronę swojej destynacji, aby zobaczyć dokładną stałą cenę przed rezerwacją.</p><h3>Jak kierowca mnie znajdzie na lotnisku?</h3><p>Kierowca czeka w wyznaczonym punkcie spotkania w hali przylotów z tabliczką z Twoim nazwiskiem. Po rezerwacji otrzymasz e-mail z danymi kierowcy i kodem QR.</p><h3>Co jeśli mój lot jest opóźniony?</h3><p>Śledzimy wszystkie loty w czasie rzeczywistym. Jeśli Twój lot jest opóźniony, kierowca czeka bezpłatnie.</p><h3>Ceny są od osoby czy za pojazd?</h3><p>Za pojazd. Do 5 pasażerów może podróżować jednym Mercedesem Vito w tej samej cenie, więc rodzina płaci tyle co osoba podróżująca samotnie.</p><h3>Czy mogę bezpłatnie anulować transfer z lotniska?</h3><p>Tak, darmowa anulacja jest możliwa do 24 godzin przed planowanym odjazdem.</p><h3>Czy realizujecie transfery w nocy?</h3><p>Tak, oferujemy transfer 24/7. Kierowca jest gotowy i czeka również na nocne loty.</p><h3>Czy mogę zarezerwować transfer z fotelikiem dziecięcym?</h3><p>Tak. Foteliki dziecięce są dostępne za $10 za rezerwację — zaznacz to przy rezerwacji, a fotelik zostanie zamontowany, zanim kierowca wyruszy na lotnisko.</p>', 'Transfer z Lotniska Antalya | Stała cena, powitanie, rezerwacja online', 'Prywatny transfer z lotniska Antalya: stała cena za pojazd, śledzenie lotu w czasie rzeczywistym i kierowca czekający w hali przylotów. Darmowa anulacja do 24 godzin.', 'Трансфер из Аэропорта Анталии', 'Частный трансфер из аэропорта Анталии (AYT) прямо до вашего отеля — одна фиксированная цена за автомобиль, водитель встречает вас в зале прилёта.', '<p>Вы бронируете до вылета, мы отслеживаем ваш рейс, а Mercedes Vito везёт вас от двери до двери. Без очереди на стоянке такси, без счётчика и без сюрпризов в конце поездки.</p><h2>Что происходит, когда вы приземляетесь в аэропорту Анталии</h2><ol><li><strong>Бронирование до вылета</strong> — Выберите направление, дату и время. Вы сразу получите письмо с подтверждением, данными водителя и QR-кодом.</li><li><strong>Мы отслеживаем ваш рейс</strong> — Укажите номер рейса при бронировании. Мы отслеживаем все рейсы в реальном времени — при задержке водитель ждёт бесплатно.</li><li><strong>Встреча в зале прилёта</strong> — Водитель встретит вас в назначенном месте встречи в зале прилёта с табличкой с вашим именем и поможет с багажом до автомобиля.</li><li><strong>От двери до двери</strong> — Прямо из аэропорта в ваш отель, виллу или по любому адресу на Турецкой Ривьере — без попутчиков и объездов.</li></ol><h2>Почему трансфер из аэропорта Анталии стоит бронировать в TORVIAN</h2><ul><li>Цены указаны за автомобиль, а не за человека — до 5 пассажиров едут в одном Mercedes Vito по одной цене.</li><li>Цена, которую вы видите при бронировании, — это цена, которую вы платите. Без скрытых сборов и повышающих коэффициентов.</li><li>Каждый рейс в аэропорт Анталии отслеживается, поэтому водитель подстроен под фактическое время посадки.</li><li>Бесплатная отмена за 24 часа до запланированного отправления.</li><li>Детское кресло — $10 за бронирование, просто укажите это при оформлении.</li><li>Мы работаем круглосуточно, поэтому ночной прилёт бронируется так же, как и любой другой.</li><li>Автомобили Mercedes Vito VIP с кожаным салоном, Wi-Fi и климат-контролем.</li><li>Оплата картой проходит через Stripe на инфраструктуре, соответствующей PCI DSS.</li></ul><h2>Часто задаваемые вопросы</h2><h3>Сколько стоит трансфер из аэропорта Анталии?</h3><p>Цена зависит только от направления и фиксирована за автомобиль, а не за человека — до 5 пассажиров платят одинаково. Откройте страницу вашего направления, чтобы увидеть точную фиксированную цену до бронирования.</p><h3>Как водитель найдёт меня в аэропорту?</h3><p>Водитель встретит вас в назначенном месте встречи в зале прилёта с табличкой с вашим именем. После бронирования вы получите email с данными водителя и QR-кодом.</p><h3>Что если мой рейс задержится?</h3><p>Мы отслеживаем все рейсы в реальном времени. При задержке рейса водитель ждёт бесплатно.</p><h3>Цены за человека или за автомобиль?</h3><p>За автомобиль. До 5 пассажиров могут путешествовать в одном Mercedes Vito по одной цене, поэтому семья платит столько же, сколько один пассажир.</p><h3>Можно ли бесплатно отменить трансфер из аэропорта?</h3><p>Да, бесплатная отмена возможна за 24 часа до запланированного отправления.</p><h3>Вы работаете ночью?</h3><p>Да, мы предоставляем трансфер 24/7. Водитель будет готов и ждать даже для ночных рейсов.</p><h3>Можно забронировать трансфер с детским креслом?</h3><p>Да. Детские кресла доступны за $10 за бронирование — укажите это при бронировании, и кресло установят до выезда водителя в аэропорт.</p>', 'Трансфер из Аэропорта Анталии | Фиксированная цена, встреча, онлайн', 'Частный трансфер из аэропорта Анталии: фиксированная цена за автомобиль, отслеживание рейса в реальном времени и водитель в зале прилёта. Бесплатная отмена за 24 часа.', 'Antalya Luchthaven Transfer', 'Privétransfer vanaf de luchthaven Antalya (AYT) rechtstreeks naar uw hotel — één vaste prijs per voertuig, met uw chauffeur die in de aankomsthal op u wacht.', '<p>U boekt voor vertrek, wij volgen uw vlucht en een Mercedes Vito brengt u van deur tot deur. Geen rij bij de taxistandplaats, geen meter die loopt, geen verrassing aan het eind van de rit.</p><h2>Wat er gebeurt als u landt op de luchthaven Antalya</h2><ol><li><strong>Boek voor u vertrekt</strong> — Kies uw bestemming, datum en tijd. U ontvangt direct een bevestiging per e-mail met de chauffeursgegevens en een QR-code.</li><li><strong>Wij volgen uw vlucht</strong> — Vul uw vluchtnummer in bij het boeken. Wij volgen alle vluchten in realtime — heeft uw vlucht vertraging, dan wacht uw chauffeur kosteloos.</li><li><strong>Ontvangst in de aankomsthal</strong> — Uw chauffeur wacht op het aangewezen punt in de aankomsthal met een bord met uw naam en begeleidt u met uw bagage naar het voertuig.</li><li><strong>Van deur tot deur</strong> — Rechtstreeks van de luchthaven naar uw hotel, villa of elk adres aan de Turkse Rivièra — zonder extra stops of omwegen.</li></ol><h2>Waarom u uw Antalya luchthaventransfer bij TORVIAN boekt</h2><ul><li>Prijzen gelden per voertuig, niet per persoon — tot 5 passagiers reizen samen in één Mercedes Vito voor dezelfde prijs.</li><li>De prijs die u bij het boeken ziet, is de prijs die u betaalt. Geen verborgen kosten, geen piektoeslagen.</li><li>Elke aankomst op de luchthaven Antalya wordt gevolgd, zodat uw chauffeur is afgestemd op uw werkelijke landingstijd.</li><li>Gratis annuleren tot 24 uur voor de geplande vertrektijd.</li><li>Kinderzitjes voor $10 per boeking — geef dit gewoon aan tijdens het boeken.</li><li>Wij rijden 24 uur per dag, dus een nachtelijke aankomst boekt u net als elke andere transfer.</li><li>Mercedes Vito VIP-voertuigen met lederen stoelen, wifi en airconditioning.</li><li>Kaartbetalingen verlopen via Stripe op PCI DSS-conforme infrastructuur.</li></ul><h2>Veelgestelde vragen</h2><h3>Wat kost een transfer vanaf de luchthaven Antalya?</h3><p>De prijs hangt alleen af van uw bestemming en staat vast per voertuig, niet per persoon — tot 5 passagiers betalen hetzelfde. Open de pagina van uw bestemming om de exacte vaste prijs te zien voordat u boekt.</p><h3>Hoe vindt mijn chauffeur mij op de luchthaven?</h3><p>Uw chauffeur wacht op het aangewezen punt in de aankomsthal met een bord met uw naam. Na uw boeking ontvangt u een e-mail met de chauffeursgegevens en een QR-code.</p><h3>Wat gebeurt er als mijn vlucht vertraging heeft?</h3><p>Wij volgen alle vluchten in realtime. Heeft uw vlucht vertraging, dan wacht uw chauffeur kosteloos.</p><h3>Zijn de prijzen per persoon of per voertuig?</h3><p>Per voertuig. Tot 5 passagiers reizen samen in één Mercedes Vito voor dezelfde prijs, dus een gezin betaalt evenveel als een alleenreizende.</p><h3>Kan ik mijn luchthaventransfer gratis annuleren?</h3><p>Ja, u kunt tot 24 uur voor de geplande vertrektijd gratis annuleren.</p><h3>Rijdt u ook ''s nachts?</h3><p>Ja, wij rijden 24 uur per dag. Ook bij nachtvluchten staat uw chauffeur voor u klaar.</p><h3>Kan ik een transfer met kinderzitje boeken?</h3><p>Ja. Kinderzitjes zijn beschikbaar voor $10 per boeking — geef dit aan tijdens het boeken, dan is het zitje geplaatst voordat uw chauffeur naar de luchthaven vertrekt.</p>', 'Antalya Luchthaven Transfer | Vaste prijs, ontvangst, online boeken', 'Privétransfer vanaf de luchthaven Antalya: vaste prijs per voertuig, realtime vluchtmonitoring en uw chauffeur wacht in de aankomsthal. Gratis annuleren tot 24 uur.', 'Transfer Aeroportul Antalya', 'Transfer privat de la Aeroportul Antalya (AYT) direct la hotelul tău — un singur preț fix per vehicul, cu șoferul care te așteaptă în holul de sosiri.', '<p>Rezervi înainte de plecare, îți urmărim zborul, iar un Mercedes Vito te duce din ușă în ușă. Fără coadă la stația de taxi, fără aparat de taxare pornit, fără surprize la capătul drumului.</p><h2>Ce se întâmplă când aterizezi pe Aeroportul Antalya</h2><ol><li><strong>Rezervi înainte de plecare</strong> — Alege destinația, data și ora. Primești imediat un e-mail de confirmare cu datele șoferului și un cod QR.</li><li><strong>Îți urmărim zborul</strong> — Scrie numărul zborului la rezervare. Urmărim toate zborurile în timp real — dacă al tău întârzie, șoferul te așteaptă fără costuri suplimentare.</li><li><strong>Întâmpinare în holul de sosiri</strong> — Șoferul te așteaptă în punctul desemnat din holul de sosiri, cu un panou pe care este scris numele tău, și te însoțește cu bagajele până la vehicul.</li><li><strong>Din ușă în ușă</strong> — Direct de la aeroport la hotelul, vila sau orice adresă de pe Riviera Turcească — fără opriri suplimentare și fără ocolișuri.</li></ol><h2>De ce să rezervi transferul de la Aeroportul Antalya cu TORVIAN</h2><ul><li>Prețurile sunt per vehicul, nu per persoană — până la 5 pasageri călătoresc împreună într-un Mercedes Vito la același preț.</li><li>Prețul pe care îl vezi la rezervare este prețul pe care îl plătești. Fără costuri ascunse, fără tarife majorate.</li><li>Fiecare sosire pe Aeroportul Antalya este urmărită, așa că șoferul este programat după ora reală de aterizare.</li><li>Anulare gratuită cu până la 24 de ore înainte de ora programată de plecare.</li><li>Scaune pentru copii la $10 per rezervare — este suficient să le ceri la rezervare.</li><li>Circulăm 24 de ore din 24, așa că o sosire de noapte se rezervă exact ca oricare alta.</li><li>Vehicule Mercedes Vito VIP cu scaune din piele, Wi-Fi și aer condiționat.</li><li>Plățile cu cardul sunt procesate prin Stripe, pe infrastructură conformă PCI DSS.</li></ul><h2>Întrebări frecvente</h2><h3>Cât costă un transfer de la Aeroportul Antalya?</h3><p>Prețul depinde doar de destinație și este fix per vehicul, nu per persoană — până la 5 pasageri plătesc la fel. Deschide pagina destinației tale ca să vezi prețul fix exact înainte de a rezerva.</p><h3>Cum mă găsește șoferul în aeroport?</h3><p>Șoferul te așteaptă în punctul desemnat din holul de sosiri, cu un panou pe care este scris numele tău. După rezervare primești un e-mail cu datele șoferului și un cod QR.</p><h3>Ce se întâmplă dacă zborul meu are întârziere?</h3><p>Urmărim toate zborurile în timp real. Dacă al tău întârzie, șoferul te așteaptă fără costuri suplimentare.</p><h3>Prețurile sunt per persoană sau per vehicul?</h3><p>Per vehicul. Până la 5 pasageri călătoresc împreună într-un Mercedes Vito la același preț, așa că o familie plătește cât o singură persoană.</p><h3>Pot anula gratuit transferul de aeroport?</h3><p>Da, poți anula gratuit cu până la 24 de ore înainte de ora programată de plecare.</p><h3>Circulați și noaptea?</h3><p>Da, circulăm 24 de ore din 24. Și pentru zborurile de noapte șoferul te așteaptă.</p><h3>Pot rezerva un transfer cu scaun pentru copii?</h3><p>Da. Scaunele pentru copii sunt disponibile la $10 per rezervare — cere-l la rezervare și va fi montat înainte ca șoferul să plece spre aeroport.</p>', 'Transfer Aeroportul Antalya | Preț fix, întâmpinare, rezervare online', 'Transfer privat de la Aeroportul Antalya: preț fix per vehicul, urmărirea zborului în timp real și șoferul te așteaptă în holul de sosiri. Anulare gratuită cu 24 de ore înainte.'
WHERE NOT EXISTS (SELECT 1 FROM landing_pages WHERE slug = 'antalya-airport-transfer');
